import{_ as e,o as a,c as t,a2 as i}from"./chunks/framework.BfI5QxtK.js";const k=JSON.parse('{"title":"Session settings","description":"","frontmatter":{},"headers":[],"relativePath":"session-settings.md","filePath":"session-settings.md"}'),n={name:"session-settings.md"};function l(o,s,r,d,p,h){return a(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="session-settings" tabindex="-1">Session settings <a class="header-anchor" href="#session-settings" aria-label="Permalink to &quot;Session settings&quot;">​</a></h1><p><a href="./configuration-reference">Configuration reference</a></p><p>Choose which GNOME controls to keep, how launchers affect window focus, and whether tools can use particular Wayland interfaces. Add the examples to <code>~/.config/gnoblin/init.lua</code>.</p><h2 id="native-features" tabindex="-1">Native features <a class="header-anchor" href="#native-features" aria-label="Permalink to &quot;Native features&quot;">​</a></h2><p>Enable GNOME&#39;s notifications if your shell does not provide a notification daemon. Run only one notification service. This example enables GNOME&#39;s notifications and leaves its keyboard-layout and window-switching popups off:</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gnoblin.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">configure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    shell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        notifications </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        input_source_switcher </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        window_switcher </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>Enables</th></tr></thead><tbody><tr><td><code>notifications</code></td><td>Initially off</td><td>GNOME&#39;s notification service</td></tr><tr><td><code>input_source_switcher</code></td><td>Initially off</td><td>Native keyboard-layout popup</td></tr><tr><td><code>window_switcher</code></td><td>Off</td><td>GNOME&#39;s app/window/group switchers</td></tr></tbody></table><p>Notifications and the layout-popup setting are saved in GNOME&#39;s settings database (GSettings). To turn them off again, set them to <code>false</code>; deleting the Lua lines leaves the saved values in place.</p><p>Removing <code>window_switcher</code> returns it to <code>false</code>. If your shell needs the same switching keys, also <a href="./shortcuts#avoid-conflicts">release or rebind the built-in shortcuts</a>.</p><p>Disabling the layout popup does not disable keyboard layouts. Volume/brightness popups and screenshot controls come from your desktop shell; these options do not enable GNOME&#39;s versions.</p><h2 id="layer-shell-keyboard-focus" tabindex="-1">Layer-shell keyboard focus <a class="header-anchor" href="#layer-shell-keyboard-focus" aria-label="Permalink to &quot;Layer-shell keyboard focus&quot;">​</a></h2><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gnoblin.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">configure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    layer_shell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        preserve_active_window </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Default: <code>true</code>. <strong>Requires logout and login.</strong></p><p>When a launcher requests exclusive keyboard focus, typing goes to the launcher. With this setting enabled, the application underneath keeps its active appearance, so its titlebar and effects do not switch to their unfocused style. Typing still goes only to the launcher.</p><p>Set <code>false</code> to let exclusive layers deactivate the application beneath them. On-demand focus, passive bars and normal application menus are unchanged.</p><h2 id="window-drag-boundary" tabindex="-1">Window drag boundary <a class="header-anchor" href="#window-drag-boundary" aria-label="Permalink to &quot;Window drag boundary&quot;">​</a></h2><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gnoblin.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">configure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    window_management </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        constrain_drag_to_work_area </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Default: <code>true</code>. Applies at the next drag after reload.</p><p>This keeps the dragged frame below the monitor&#39;s reserved top area, including space reserved by a layer-shell panel. Set <code>false</code> to allow overlap.</p><h2 id="protocol-settings" tabindex="-1">Protocol settings <a class="header-anchor" href="#protocol-settings" aria-label="Permalink to &quot;Protocol settings&quot;">​</a></h2><p>Wayland protocols let desktop tools request features such as screen capture, clipboard access and display power control. The interfaces below are enabled by default. Most users can leave them alone.</p><p>For example, this disables the <code>wlr_screencopy</code> screen-capture interface:</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">gnoblin.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">configure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    protocols </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        wlr_screencopy </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>Log out and back in</strong> to apply protocol changes. Gnoblin exposes these interfaces when the session starts and cannot remove them during config reload.</p><table tabindex="0"><thead><tr><th>Name</th><th>Used for</th></tr></thead><tbody><tr><td><code>wlr_layer_shell</code></td><td>Bars, docks and launchers</td></tr><tr><td><code>wlr_screencopy</code></td><td>Screen capture</td></tr><tr><td><code>ext_foreign_toplevel_list</code></td><td>Window enumeration</td></tr><tr><td><code>wlr_foreign_toplevel_management</code></td><td>Window controls and dock targets</td></tr><tr><td><code>ext_data_control</code></td><td>Clipboard managers</td></tr><tr><td><code>ext_idle_notify</code></td><td>Idle detection</td></tr><tr><td><code>wlr_gamma_control</code></td><td>Gamma and colour temperature</td></tr><tr><td><code>wlr_output_power_management</code></td><td>Display power</td></tr><tr><td><code>ext_background_effect_v1</code></td><td>Client-requested background blur</td></tr><tr><td><code>xdg_decoration</code></td><td>Client/server titlebar negotiation</td></tr><tr><td><code>window_frame_renderer</code></td><td>External frame renderer service</td></tr><tr><td><code>blur_fade</code></td><td>Per-item blur fade metadata</td></tr></tbody></table><p>This does not block all screen sharing: apps using the desktop portal follow <a href="./permissions">portal permissions</a> instead. Disabling protocols your shell uses can prevent its features from working. See the <a href="./wayland-protocols">protocol catalog</a> for the advertised interface names, related guides and interfaces that are not yet supported.</p>`,26)])])}const g=e(n,[["render",l]]);export{k as __pageData,g as default};
